-- Shared helpers for the PostgreSQL schema. See docs/postgresql-migration.md.
--
-- Port rules used by every migration in this folder:
-- * SQLite INTEGER -> bigint (Rust i64), including 0/1 flags, so existing i64
--   binds and decodes keep working. Flags stay 0/1.
-- * AUTOINCREMENT keys -> bigint GENERATED BY DEFAULT AS IDENTITY. BY DEFAULT
--   lets the data load (and test fixtures) keep explicit IDs; reset the
--   sequence afterwards with setval().
-- * TEXT stays text, including JSON documents and 'YYYY-MM-DD HH:MM:SS' UTC
--   timestamps, so Rust code keeps binding and reading String. JSON is read
--   with the sprk_json* helpers below (parsed per call, as SQLite does).
--   Converting hot columns to jsonb/timestamptz is a later, per-column step.
-- * SQLite triggers -> PL/pgSQL trigger functions with the same effects.
-- * Helpers call each other schema-qualified: index maintenance (CREATE INDEX,
--   REINDEX, VACUUM) runs with search_path = pg_catalog.
--
-- Times use statement_timestamp() in UTC: SQLite's 'now' is fixed per
-- statement, not per transaction.

-- SQLite datetime('now') / datetime(value, modifier): 'YYYY-MM-DD HH:MM:SS'.
-- value is 'now' or a 'YYYY-MM-DD[ HH:MM:SS]' text; modifier is an interval
-- such as '-5 seconds' or '+1 day'.
CREATE FUNCTION sprk_datetime(value text, modifier text DEFAULT NULL) RETURNS text
LANGUAGE sql STABLE PARALLEL SAFE
AS $$
    SELECT to_char(
        CASE WHEN value = 'now' THEN statement_timestamp() AT TIME ZONE 'UTC' ELSE value::timestamp END
            + COALESCE(modifier::interval, interval '0'),
        'YYYY-MM-DD HH24:MI:SS')
$$;

-- SQLite date('now') / date(value, modifier): 'YYYY-MM-DD'.
CREATE FUNCTION sprk_date(value text, modifier text DEFAULT NULL) RETURNS text
LANGUAGE sql STABLE PARALLEL SAFE
AS $$ SELECT left(public.sprk_datetime(value, modifier), 10) $$;

-- Current time as stored in timestamp columns (SQLite datetime('now')).
CREATE FUNCTION sprk_now() RETURNS text
LANGUAGE sql STABLE PARALLEL SAFE
AS $$ SELECT public.sprk_datetime('now') $$;

-- UTC day key, equal to SQLite date('now').
CREATE FUNCTION sprk_utc_day() RETURNS text
LANGUAGE sql STABLE PARALLEL SAFE
AS $$ SELECT public.sprk_date('now') $$;

-- SQLite strftime('%s', value) / unixepoch(value): epoch seconds of a
-- 'YYYY-MM-DD HH:MM:SS' UTC text or 'now'.
CREATE FUNCTION sprk_epoch(value text DEFAULT 'now') RETURNS bigint
LANGUAGE sql STABLE PARALLEL SAFE
AS $$
    -- floor: SQLite truncates to whole seconds; a bigint cast would round.
    SELECT floor(extract(epoch FROM CASE WHEN value = 'now' THEN statement_timestamp()
                                   ELSE value::timestamp AT TIME ZONE 'UTC' END))::bigint
$$;

-- SQLite JSON path ('$', '$.a.b', '$.a[0].c', '$.a."12"') -> PostgreSQL
-- path array.
CREATE FUNCTION sprk_json_path(path text) RETURNS text[]
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
AS $$
    SELECT COALESCE(array_agg(COALESCE(m[1], m[2], m[3]) ORDER BY n), '{}')
    FROM regexp_matches(path, '\."([^"]*)"|\.([^."\[]+)|\[(\d+)\]', 'g') WITH ORDINALITY AS t(m, n)
$$;

-- SQLite json_extract(doc, path) as jsonb. JSON null and missing values are
-- SQL NULL, as in SQLite.
CREATE FUNCTION sprk_json(doc text, path text) RETURNS jsonb
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
AS $$ SELECT NULLIF(doc::jsonb #> public.sprk_json_path(path), 'null'::jsonb) $$;

-- Integer read with SQLite json_extract() semantics: numbers become bigint,
-- JSON true/false become 1/0, everything else (missing, null, strings,
-- arrays, objects) is NULL. Never raises on valid JSON, so it is safe in
-- index predicates and triggers.
CREATE FUNCTION sprk_json_int(value jsonb) RETURNS bigint
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
AS $$
    SELECT CASE jsonb_typeof(value)
        WHEN 'number' THEN value::numeric::bigint
        WHEN 'boolean' THEN CASE WHEN value::boolean THEN 1 ELSE 0 END
    END
$$;
CREATE FUNCTION sprk_json_int(doc text, path text) RETURNS bigint
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
AS $$ SELECT public.sprk_json_int(doc::jsonb #> public.sprk_json_path(path)) $$;

-- Real-number read (SQLite json_extract on a number).
CREATE FUNCTION sprk_json_real(doc text, path text) RETURNS double precision
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
AS $$
    SELECT CASE jsonb_typeof(v) WHEN 'number' THEN v::numeric::double precision
                                WHEN 'boolean' THEN CASE WHEN v::boolean THEN 1 ELSE 0 END END
    FROM (SELECT doc::jsonb #> public.sprk_json_path(path) AS v) s
$$;

-- Text read: JSON strings unquoted, numbers as their text, true/false as
-- 1/0 (SQLite), arrays and objects as JSON text, null/missing as NULL.
CREATE FUNCTION sprk_json_text(doc text, path text) RETURNS text
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
AS $$
    SELECT CASE jsonb_typeof(v)
        WHEN 'string' THEN v #>> '{}'
        WHEN 'boolean' THEN CASE WHEN v::boolean THEN '1' ELSE '0' END
        WHEN 'null' THEN NULL
        ELSE v::text
    END
    FROM (SELECT doc::jsonb #> public.sprk_json_path(path) AS v) s
$$;

-- SQLite json_type(doc, path): null, true, false, integer, real, text,
-- array, object; NULL when the path is missing.
CREATE FUNCTION sprk_json_type(doc text, path text DEFAULT '$') RETURNS text
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
AS $$
    SELECT CASE jsonb_typeof(v)
        WHEN 'number' THEN CASE WHEN v::numeric = trunc(v::numeric) AND v::text !~ '[.eE]' THEN 'integer' ELSE 'real' END
        WHEN 'boolean' THEN v::text
        WHEN 'string' THEN 'text'
        ELSE jsonb_typeof(v)
    END
    FROM (SELECT doc::jsonb #> public.sprk_json_path(path) AS v) s
$$;

-- SQLite json_array_length(): arrays give their length, any other value 0,
-- a missing value NULL. jsonb_array_length raises on scalars instead.
CREATE FUNCTION sprk_json_array_length(value jsonb) RETURNS bigint
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
AS $$ SELECT CASE WHEN jsonb_typeof(value) = 'array' THEN jsonb_array_length(value) ELSE 0 END $$;
CREATE FUNCTION sprk_json_array_length(doc text, path text DEFAULT '$') RETURNS bigint
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
AS $$ SELECT public.sprk_json_array_length(doc::jsonb #> public.sprk_json_path(path)) $$;

-- SQLite json_set(doc, path, value) for one path. A NULL document stays
-- NULL; a NULL value stores JSON null. Overloads pick the JSON type from
-- the argument: bigint/double -> number, boolean -> true/false,
-- text -> string, jsonb -> embedded JSON (SQLite json(?)).
CREATE FUNCTION sprk_json_set(doc text, path text, value jsonb) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE
AS $$
    SELECT CASE WHEN doc IS NULL THEN NULL
        ELSE jsonb_set(doc::jsonb, public.sprk_json_path(path), COALESCE(value, 'null'::jsonb), true)::text END
$$;
CREATE FUNCTION sprk_json_set(doc text, path text, value text) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE
AS $$ SELECT public.sprk_json_set(doc, path, to_jsonb(value)) $$;
CREATE FUNCTION sprk_json_set(doc text, path text, value bigint) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE
AS $$ SELECT public.sprk_json_set(doc, path, to_jsonb(value)) $$;
CREATE FUNCTION sprk_json_set(doc text, path text, value double precision) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE
AS $$ SELECT public.sprk_json_set(doc, path, to_jsonb(value)) $$;
CREATE FUNCTION sprk_json_set(doc text, path text, value boolean) RETURNS text
LANGUAGE sql IMMUTABLE PARALLEL SAFE
AS $$ SELECT public.sprk_json_set(doc, path, to_jsonb(value)) $$;

-- SQLite json_remove(doc, path) for one path.
CREATE FUNCTION sprk_json_remove(doc text, path text) RETURNS text
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
AS $$ SELECT (doc::jsonb #- public.sprk_json_path(path))::text $$;

-- SQLite json_each(doc[, path]): one row per array element (key = index) or
-- object member. value is what SQLite returns (strings unquoted, numbers and
-- nested JSON as text); element is the element as jsonb.
CREATE FUNCTION sprk_json_each(doc text, path text DEFAULT '$') RETURNS TABLE(key text, value text, element jsonb)
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
AS $$
    SELECT e.key,
           CASE jsonb_typeof(e.value) WHEN 'string' THEN e.value #>> '{}' WHEN 'null' THEN NULL ELSE e.value::text END,
           e.value
    FROM (SELECT doc::jsonb #> public.sprk_json_path(path) AS v) s,
    LATERAL (
        SELECT (a.n - 1)::text AS key, a.value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(s.v) = 'array' THEN s.v END) WITH ORDINALITY AS a(value, n)
        UNION ALL
        SELECT o.key, o.value FROM jsonb_each(CASE WHEN jsonb_typeof(s.v) = 'object' THEN s.v END) AS o
    ) e
$$;

-- Integer elements of a JSON array (SQLite: SELECT value FROM json_each(?)).
CREATE FUNCTION sprk_json_ints(doc text) RETURNS SETOF bigint
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
AS $$ SELECT public.sprk_json_int(e) FROM jsonb_array_elements(doc::jsonb) AS e $$;
